67	async fn spawn_response(bytes: &'static [u8]) -> String {
68	    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
69	    let addr = listener.local_addr().unwrap();
70	    tokio::spawn(async move {
71	        let (mut socket, _) = listener.accept().await.unwrap();
72	        let mut request = [0u8; 4096];
73	        let _ = socket.read(&mut request).await;
74	        let headers = format!(
75	            "HTTP/1.1 200 OK\r\n\
76	             Content-Length: {}\r\n\
77	             Content-Type: application/octet-stream\r\n\
78	             Connection: close\r\n\
79	             \r\n",
80	            bytes.len(),
81	        );
82	        socket.write_all(headers.as_bytes()).await.unwrap();
83	        socket.write_all(bytes).await.unwrap();
84	        socket.flush().await.unwrap();
85	    });
86	    format!("http://{addr}/foo/-/foo-1.0.0.tgz")
87	}
