/// Tee an upstream response to the client while caching it. Each chunk is
/// forwarded to the returned [`Body`], written to `write`'s temp file, and
/// fed to the SRI checker as it arrives, so the client starts receiving
/// bytes before the full body is on disk.
///
/// The status line is committed the moment this returns `Ok`, so failures
/// that only become visible mid-transfer cannot be reported as an HTTP
/// error — they surface as an error on the response body instead, and the
/// half-written temp file is never promoted:
///
/// * A declared `Content-Length` above `max_bytes` is the one failure caught
///   synchronously, before any bytes move: this returns
///   [`TarballStreamError::TooLarge`] and `write` drops (removing its temp
///   file) without a body ever being built.
/// * On an SRI mismatch the client still receives every byte the upstream
///   sent (it runs its own verification); the temp file is abandoned rather
///   than promoted.
/// * An upstream transport error or truncation surfaces as a body-level
///   error and abandons the temp file.
/// * Dropping the body mid-stream (client disconnect) drops the carried
///   [`TarballWrite`], whose [`Drop`] removes the temp file.
///
/// Only a full body that passes SRI is promoted, via
/// [`TarballWrite::finalize`], after the last chunk is streamed.
pub fn stream_verified_to_cache(
    response: reqwest::Response,
    write: TarballWrite,
    integrity: &Integrity,
    max_bytes: u64,
) -> Result<Body, TarballStreamError> {
    if let Some(received) = response.content_length()
        && received > max_bytes
    {
        // `write` drops here, so its temp file is removed before we return.
        return Err(TarballStreamError::TooLarge { limit: max_bytes, received });
    }
    let checker = integrity_checker(integrity).map_err(TarballStreamError::Integrity)?;
    let state = TarballTee {
        url: response.url().to_string(),
        upstream: response.bytes_stream(),
        write: Some(write),
        checker: Some(checker),
        written: 0,
        max_bytes,
    };
    Ok(Body::from_stream(stream::unfold(Some(state), tee_step)))
