struct TarballTee<S> {
    url: String,
    upstream: S,
    write: Option<TarballWrite>,
    checker: Option<IntegrityChecker>,
    written: u64,
    max_bytes: u64,
}

impl<S> TarballTee<S> {
    /// Stop caching this transfer: drop the write handle (its [`Drop`]
    /// removes the temp file) and the checker so no bytes get promoted.
    fn give_up_cache(&mut self) {
        self.write = None;
        self.checker = None;
